                    "maritime.gateway.security.default-auth-mode=none",
                    "maritime.gateway.security.routes[0].id=open",
                    "maritime.gateway.security.routes[0].paths[0]=/**",
                    "maritime.gateway.security.routes[0].auth-mode=jwt-or-hmac"
            ).run(ctx -> {
